"""Security alert model generated by detection rules matching event telemetry."""

import enum
import uuid
from typing import TYPE_CHECKING, Optional

from sqlalchemy import (
    JSON,
    Enum,
    ForeignKey,
    Index,
    Integer,
    String,
    Text,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, PrimaryKeyUUIDMixin, TimestampMixin
from app.models.rule import RuleSeverity

if TYPE_CHECKING:
    from app.models.incident import Incident
    from app.models.rule import DetectionRule
    from app.models.user import User


class AlertStatus(str, enum.Enum):
    """Lifecycle disposition state of a security alert."""
    NEW = "new"                                  # Unreviewed, pending triage
    TRIAGED = "triaged"                          # Initial assessment completed
    INVESTIGATING = "investigating"              # Under active analysis
    ESCALATED = "escalated"                      # Promoted to an active Incident
    CLOSED_FALSE_POSITIVE = "closed_false_positive"  # Benign activity or noisy rule
    CLOSED_RESOLVED = "closed_resolved"          # Remediated without incident declaration


class SecurityAlert(Base, PrimaryKeyUUIDMixin, TimestampMixin):
    """Actionable alert generated when telemetry satisfies a detection rule criteria."""

    __tablename__ = "security_alerts"

    rule_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("detection_rules.id", ondelete="RESTRICT"),
        nullable=False,
        index=True,
        doc="Triggering detection rule",
    )
    title: Mapped[str] = mapped_column(
        String(200),
        nullable=False,
        index=True,
        doc="Summary alert headline",
    )
    description: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        doc="Contextual justification for the alert generation",
    )
    severity: Mapped[RuleSeverity] = mapped_column(
        Enum(RuleSeverity, name="rule_severity_enum", native_enum=False),
        nullable=False,
        index=True,
    )
    status: Mapped[AlertStatus] = mapped_column(
        Enum(AlertStatus, name="alert_status_enum", native_enum=False),
        default=AlertStatus.NEW,
        nullable=False,
        index=True,
    )
    deduplication_key: Mapped[str] = mapped_column(
        String(128),
        nullable=False,
        index=True,
        doc="Fingerprint (rule_id:entity_ip:entity_user:hour_bucket) mitigating alert fatigue and storms",
    )
    event_count: Mapped[int] = mapped_column(
        Integer,
        default=1,
        nullable=False,
        doc="Total volume of telemetry events aggregated into this alert instance",
    )
    context_data: Mapped[dict] = mapped_column(
        JSON,
        nullable=False,
        doc="Evidence artifacts including matched IPs, usernames, processes, and sample event IDs",
    )

    # Assignment & Escalation
    assigned_to_id: Mapped[Optional[uuid.UUID]] = mapped_column(
        ForeignKey("users.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
        doc="SOC analyst currently responsible for reviewing this alert",
    )
    incident_id: Mapped[Optional[uuid.UUID]] = mapped_column(
        ForeignKey("incidents.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
        doc="Associated incident case file if escalated",
    )

    # Relationships
    rule: Mapped["DetectionRule"] = relationship(
        "DetectionRule",
        back_populates="alerts",
    )
    assigned_to: Mapped[Optional["User"]] = relationship(
        "User",
        back_populates="assigned_alerts",
    )
    incident: Mapped[Optional["Incident"]] = relationship(
        "Incident",
        back_populates="alerts",
    )

    __table_args__ = (
        Index("idx_alerts_status_sev", "status", "severity"),
        Index("idx_alerts_dedup_time", "deduplication_key", "created_at"),
    )

    def __repr__(self) -> str:
        return f"<SecurityAlert {self.id} title='{self.title}' status={self.status} sev={self.severity}>"
